     1→<#
     2→.SYNOPSIS
     3→  Local server for the MiniMax OPTIMUS Control Center.
     4→
     5→.DESCRIPTION
     6→  A file:// HTML page cannot execute PowerShell, so "live daemon monitoring"
     7→  and "clickable command buttons" both require a local HTTP origin. This
     8→  server provides it and is deliberately small.
     9→
    10→  Routes
    11→    GET  /            -> index.html
    12→    GET  /api/state   -> live state JSON (freshly measured every request)
    13→    POST /api/action  -> run a whitelisted action, return its output
    14→    GET  /api/health  -> server self-check
    15→
    16→  SECURITY
    17→    - Binds 127.0.0.1 only. Never reachable off-box.
    18→    - Actions are resolved from a WHITELIST keyed by id, taken from
    19→      collect-state.ps1. The HTTP body supplies only an id, never a command,
    20→      so a crafted request cannot execute arbitrary shell.
    21→    - Action output is size-capped.
    22→#>
    23→[CmdletBinding()]
    24→param(
    25→  [int]$Port = 8900,
    26→  [switch]$NoBrowser
    27→)
    28→
    29→$ErrorActionPreference = 'Stop'
    30→$ROOT = Split-Path -Parent $PSScriptRoot
    31→$COLLECT = Join-Path $PSScriptRoot 'collect-state.ps1'
    32→$INDEX = Join-Path $ROOT 'index.html'
    33→
    34→if (-not (Test-Path $INDEX)) { throw "index.html not found at $INDEX" }
    35→
    36→# Resolve an action id to a command. The id comes from the collector, so this
    37→# is the single place a command string is ever defined for the dashboard.
    38→$ACTIONS = @{
    39→  'status'        = { & "$ROOT\..\scripts\optimus.cmd" status }
    40→  'doctor'        = { & "$ROOT\..\scripts\optimus.cmd" doctor --deep }
    41→  'census'        = { & "$ROOT\..\scripts\optimus.cmd" docker census }
    42→  'bridge_health' = { & "$ROOT\..\scripts\optimus.cmd" bridge health }
    43→  'sot_list'      = { & "$ROOT\..\scripts\optimus.cmd" sot list }
    44→  'skills'        = { & "$ROOT\..\scripts\optimus.cmd" skills list }
    45→  'qwen_status'   = { & "$ROOT\..\scripts\optimus.cmd" qwen status }
    46→  'qwen_doctor'   = { & "$ROOT\..\scripts\optimus.cmd" qwen doctor }
    47→  'state_doc'     = { & powershell -NoProfile -ExecutionPolicy Bypass -File "$ROOT\..\scripts\build-current-state.ps1" 2>&1 }
    48→  'mojibake'      = { & powershell -NoProfile -ExecutionPolicy Bypass -File "$ROOT\..\scripts\repair-mojibake.ps1" 2>&1 }
    49→  'journal'       = {
    50→                      # Read the journal with docker exec, exactly like every
    51→                      # other action shells out to an external process. Calling
    52→                      # back into http://127.0.0.1:8900/api/journal DEADLOCKS:
    53→                      # the request loop is serial, so the action would wait on
    54→                      # the very server that is busy running it.
    55→                      $raw = & docker exec minimax-hermes-bridge sh -c "tail -n 40 /opt/optimus/journal/minimax-hermes-bridge.jsonl 2>/dev/null" 2>&1 | Out-String
    56→                      $recs = @()
    57→                      foreach ($l in ($raw -split "`n")) {
    58→                        if ($l.Trim()) { try { $recs += ($l | ConvertFrom-Json) } catch { } }
    59→                      }
    60→                      if (-not $recs.Count) {
    61→                        'Journal is empty. The bridges write to it when actions run through them.'
    62→                      } else {
    63→                        "bridge  : minimax-hermes-bridge`nrecords: $($recs.Count)`n"
    64→                        (($recs | Select-Object -Last 15 | ForEach-Object { "  $($_.ts)  [$($_.event)]  $($_.detail)" }) -join "`n")
    65→                      }
    66→                    }
    67→  'compose_check' = { docker compose -f 'C:\Users\apviz\docker-compose.yml' config --quiet; "exit=$LASTEXITCODE" }
    68→  'app_status'    = { & "$ROOT\..\scripts\optimus.cmd" app status }
    69→  'ai_auth'       = { & mcode-tools auth status }
    70→  'ai_tools'      = { & mcode-tools connector tools }
    71→}
    72→
    73→Write-Host "OPTIMUS Control Center" -ForegroundColor Cyan
    74→Write-Host "  state  : GET  http://127.0.0.1:$Port/api/state" -ForegroundColor DarkGray
    75→Write-Host "  ui     : GET  http://127.0.0.1:$Port/" -ForegroundColor DarkGray
    76→Write-Host "  loopback only. Ctrl+C to stop." -ForegroundColor DarkGray
